use semio_framework_os_infinite::world::{World3dBuildContext,WorldCursorWakeAuthority};
use semio_framework_job::{StepContext,StepBudget,OperationId,Generation,CancelToken};
use semio_framework_value::RetainedCloneGrant;
use semio_framework_trace::observe_heap_allocations_on_this_thread as observed;
#[global_allocator]
static ORIGINAL_HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
#[test]
fn original_world_partial_page_birth_and_unique_shared_authority_retire_exact_owned_backings(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let grant:RetainedCloneGrant=serde_json::from_value(law["grant"].clone()).unwrap();
 for alias in law["aliases"].as_array().unwrap(){for cut in law["cuts"].as_array().unwrap(){
  let(root,root_birth)=CancelToken::admit_root(grant).unwrap().unwrap();let mut sequence=0;let(authority,heap)=observed(WorldCursorWakeAuthority::new);let mut born=heap.requested_bytes;let mut released=heap.released_bytes;
  let(mut first,heap)=observed(||World3dBuildContext::new(authority.clone()));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let mut second=Some(World3dBuildContext::new(authority));
  if alias=="unique"{let second=second.as_mut().unwrap();for _ in 0..10000{if second.terminal_is_empty(){break}let mut receipt=Default::default();let mut cx=StepContext::new(OperationId(71002),Generation(3),StepBudget::new(1,12345,grant),root.clone(),||Some(1),&mut sequence,&mut receipt);let(step,heap)=observed(||second.close_step(&mut cx).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.requested_bytes;released+=heap.released_bytes;}assert!(second.terminal_is_empty());}
  for _ in 0..cut.as_u64().unwrap(){let mut receipt=Default::default();let mut denied=StepContext::new(OperationId(71002),Generation(3),StepBudget::new(0,12345,grant),root.clone(),||Some(1),&mut sequence,&mut receipt);let(_,heap)=observed(||first.prepare_step(&mut denied).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));drop(denied);let mut receipt=Default::default();let mut cx=StepContext::new(OperationId(71002),Generation(3),StepBudget::new(1,12345,grant),root.clone(),||Some(1),&mut sequence,&mut receipt);let(_,heap)=observed(||first.prepare_step(&mut cx).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(cx.retained_progress().retained_capacity_bytes,cx.retained_progress().released_bytes));born+=heap.requested_bytes;released+=heap.released_bytes;}
  for owner in [&mut first,second.as_mut().unwrap()]{for turn in 0..10000{if owner.terminal_is_empty(){break}let mut receipt=Default::default();let mut cx=StepContext::new(OperationId(71002),Generation(3),StepBudget::new(1,12345,grant),root.clone(),||Some(1),&mut sequence,&mut receipt);let(step,heap)=observed(||owner.close_step(&mut cx).unwrap());assert_eq!(step.progress(),cx.retained_progress());assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.requested_bytes;released+=heap.released_bytes;assert!(turn<9999);}assert!(owner.terminal_is_empty());}
  assert_eq!(born,released);assert_eq!(observed(||{drop(first);drop(second)}).1.released_bytes,0);let mut root=semio_framework_async::CancelTokenRetirement::from_token(root);let mut freed=0;while !root.terminal_is_empty(){let(step,heap)=observed(||root.close_step(grant).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));freed+=heap.released_bytes;}assert_eq!(freed,root_birth.retained_capacity_bytes);eprintln!("[DEBUG] Original World cut={cut} alias={alias} original physical birth/free={born} denied0 terminalDrop0");
 }}
}
